pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposit1, uint256 deposit2) public {
        // Keep deposits within a reasonable range but allow overflow exploration
        uint256 maxDeposit = type(uint256).max / 3;
        deposit1 = bound(deposit1, 0, maxDeposit);
        deposit2 = bound(deposit2, 0, maxDeposit);

        // Setup two actors
        address alice = makeAddr("alice");
        address bob = makeAddr("bob");

        // Fund actors with enough ETH for deposits
        vm.deal(alice, deposit1 + 1 ether);
        vm.deal(bob, deposit2 + 1 ether);

        // Alice deposits
        vm.prank(alice);
        c.addToBalance{value: deposit1}();

        // Bob deposits
        vm.prank(bob);
        c.addToBalance{value: deposit2}();

        // Check contract has enough ETH to cover all balances (invariant is that balances add up to total ETH)
        uint256 totalBalance = c.getBalance(alice) + c.getBalance(bob);
        if (totalBalance > address(c).balance) {
            // If invariant broken, withdrawBalance() should fail for someone
            bool aliceWithdrawSuccess = true;
            bool bobWithdrawSuccess = true;

            vm.prank(alice);
            try c.withdrawBalance() {
                aliceWithdrawSuccess = true;
            } catch {
                aliceWithdrawSuccess = false;
            }

            vm.prank(bob);
            try c.withdrawBalance() {
                bobWithdrawSuccess = true;
            } catch {
                bobWithdrawSuccess = false;
            }

            // In the correct version, both should succeed. In the buggy version, at least one fails.
            assertTrue(aliceWithdrawSuccess && bobWithdrawSuccess);
        } else {
            // If invariant holds, both withdraws should succeed
            vm.prank(alice);
            c.withdrawBalance();

            vm.prank(bob);
            c.withdrawBalance();

            // Should not revert, if it reaches here both succeeded
            assertTrue(true);
        }
    }
}

