pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 prevBalance) public {
        // Restrict to admissible domain: amounts that don't overflow on addition
        vm.assume(amount + prevBalance >= amount);
        vm.assume(amount + prevBalance >= prevBalance);
        address caller = address(0xdead);
        vm.assume(caller != address(c)); // avoid the contract itself

        // Give caller native ether to send and a previous balance via addToBalance with a funded fresh address
        vm.deal(caller, amount);
        // Set up prevBalance by sending a prior deposit from a different funded address
        address funder = address(0xbeef);
        vm.deal(funder, prevBalance);
        vm.prank(funder);
        c.addToBalance{value: prevBalance}();
        // Now caller performs addToBalance with amount
        vm.prank(caller);
        c.addToBalance{value: amount}();

        // Universal property: caller's balance after addToBalance is >= amount sent
        assertTrue(c.getBalance(caller) >= amount);
    }
}

