pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address sender) public {
        // Keep amounts in a range that avoids overflow in the reference's add_uint256
        amount1 = bound(amount1, 0, type(uint256).max / 2);
        amount2 = bound(amount2, 0, type(uint256).max / 2);
        vm.assume(sender != address(0) && sender != address(c));

        // Deploy a re-entrant attacker that withdraws during addToBalance
        ReentrantAttacker attacker = new ReentrantAttacker(c, sender);

        // Fund the attacker
        vm.deal(address(attacker), amount1 + amount2);

        // First deposit through the attacker
        vm.prank(address(attacker));
        attacker.deposit{value: amount1}();

        // Record the balance after the first deposit
        uint256 balanceAfterFirst = c.getBalance(sender);

        // The attacker now calls deposit again which will trigger addToBalance and re-enter withdrawBalance
        vm.prank(address(attacker));
        attacker.deposit{value: amount2}();

        // The invariant: the final balance of the intended sender is at least the value sent in the first deposit.
        // The mutant resets the sender's balance to zero before adding msg.value, losing the first deposit
        // when the re-entrant withdraw reads the balance mid-execution.
        uint256 finalBalance = c.getBalance(sender);
        assertTrue(finalBalance >= balanceAfterFirst);
    }
}

contract ReentrantAttacker {
    C public c;
    address public targetUser;
    bool private reentered;

    constructor(C _c, address _targetUser) {
        c = _c;
        targetUser = _targetUser;
    }

    function deposit() external payable {
        c.addToBalance{value: msg.value}();
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            // During addToBalance, after the sender's balance is modified,
            // re-enter and withdraw the target user's balance
            vm.prank(address(c)); // simulate the call coming from c's context? No, we just call withdraw.
            // But withdraw checks msg.sender == caller, so we need to call withdraw on c as the target user.
            // The attacker cannot withdraw as the target user directly; it attacks the balance bookkeeping.
            // Actually the attacker's goal is to observe the intermediate state.
            // Revert the attack to demonstrate only the state corruption:
            // We simply call getBalance to observe the balance, that's enough? No, assertion needs state difference.
            // We make the attacker withdraw its own balance, but it's acting on behalf of the victim's balance in the bug.
            // Redesign: The attacker triggers addToBalance for the target user by sending from attacker? addToBalance always uses msg.sender.
            // To make msg.sender == targetUser, the attacker would need to be the targetUser.
            // Instead, the adversary is the target user itself! The target user deposits via the attacker contract.
            // The attacker contract is the msg.sender for addToBalance. So targetUser is the attacker contract.
            // In setup, targetUser == attacker address. ReentrantAttacker's receive() calls withdrawBalance on c.
            // In the bug, the balance was reset to 0 before adding, so withdraw sees 0, then the second deposit adds amount2.
            // The final balance equals amount2, losing amount1. The reference's add_uint256 adds amount2 to the existing amount1.
            c.withdrawBalance();
            reentered = false;
        }
    }
}

