pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReentrantAttacker attacker;
    function setUp() public {
        c = new C();
        attacker = new ReentrantAttacker(c);
        vm.deal(address(attacker), 10 ether);
    }
    function testFuzz_property(address victim, uint256 victimAmount, uint256 attackerAmount) public {
        vm.assume(victim != address(0));
        vm.assume(victim != address(attacker));
        vm.assume(victim != address(c));
        vm.assume(victimAmount > 0 && victimAmount <= 1 ether);
        vm.assume(attackerAmount > 0 && attackerAmount <= 1 ether);
        // Give victim a known balance via addToBalance
        vm.deal(victim, victimAmount);
        vm.prank(victim);
        c.addToBalance{value: victimAmount}();
        uint256 victimBalBefore = c.getBalance(victim);
        // Have attacker call withdrawBalance, which reenters addToBalance during the external call
        // The attacker's receive function will call addToBalance with attackerAmount Ether,
        // resetting the attacker's balance to zero in the buggy version and possibly zeroing the victim's balance.
        attacker.attack(attackerAmount);
        // After the reentrant call settles, the victim's balance must remain unchanged
        // (the attacker can only affect its own balance, not steal or zero the victim's).
        uint256 victimBalAfter = c.getBalance(victim);
        assertTrue(victimBalBefore == victimBalAfter);
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public attackAmount;
    constructor(C _target) {
        target = _target;
    }
    function attack(uint256 amount) external payable {
        attackAmount = amount;
        uint256 myBal = target.getBalance(address(this));
        if (myBal == 0) {
            // Deposit some Ether so we have a balance to withdraw
            target.addToBalance{value: amount}();
        }
        target.withdrawBalance();
    }
    receive() external payable {
        if (attackAmount > 0) {
            uint256 amt = attackAmount;
            attackAmount = 0;
            target.addToBalance{value: amt}();
        }
    }
}

