import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReentrantExploiter attacker;
    function setUp() public {
        c = new C();
        attacker = new ReentrantExploiter(c);
        vm.deal(address(attacker), 10 ether);
        attacker.prepare();
    }
    function testFuzz_property(uint256 depositAmount) public {
        vm.assume(depositAmount > 0 && depositAmount <= 1 ether);
        uint256 balanceBefore = c.getBalance(address(attacker));
