pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address attacker;

    function setUp() public {
        c = new C();
        attacker = address(new Attacker(c));
        vm.deal(attacker, 1 ether);
    }

    function testFuzz_property(uint256 amount) public {
        // keep amount in admissible range: positive and not exceeding attacker's balance
        vm.assume(amount > 0 && amount <= address(attacker).balance);
        // start the attack: pre-deposit something so the reentrant target has a balance to steal
        vm.prank(attacker);
        c.addToBalance{value: 0.5 ether}();
        // now the fuzzed call: attacker sends 'amount' to addToBalance, which triggers reentrancy
        vm.prank(attacker);
        c.addToBalance{value: amount}();
        // after the call, the caller's balance must be >= amount
        uint256 bal = c.getBalance(attacker);
        assertTrue(bal >= amount, "balance should be >= deposited amount");
    }
}

contract Attacker {
    C public target;
    bool private locked;

    constructor(C _target) {
        target = _target;
    }

    receive() external payable {
        if (!locked) {
            locked = true;
            // re-enter withdrawBalance to drain own balance before the addToBalance state update
            target.withdrawBalance();
            locked = false;
        }
    }
}

