pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawCallerSeed) public {
        // Restrict deposit to a reasonable range to avoid overflow issues in the test setup,
        // but keep it wide enough to allow the fuzzer to explore.
        vm.assume(depositAmount > 0 && depositAmount < type(uint128).max);

        // Determine a deterministic but fuzzed address for the withdraw caller.
        address withdrawCaller = address(uint160(uint256(keccak256(abi.encodePacked(withdrawCallerSeed)))));
        // Exclude zero address and the test contract to keep calls admissible.
        vm.assume(withdrawCaller != address(0) && withdrawCaller != address(this));

        // Fund the withdraw caller with ether for deposit.
        vm.deal(withdrawCaller, depositAmount);

        // Deposit ether into the contract via addToBalance.
        vm.prank(withdrawCaller);
        c.addToBalance{value: depositAmount}();

        // Ensure the balance to withdraw is non-zero to avoid trivial reverts.
        vm.assume(c.getBalance(withdrawCaller) > 0);

        // Withdraw the balance.
        vm.prank(withdrawCaller);
        c.withdrawBalance();

        // After withdrawBalance completes, the contract should be reentrant-able:
        // the nonReentrant modifier should have released the lock (locked_ == false).
        // We assert this by checking that another call to addToBalance (with any sender)
        // succeeds, not reverts, which it should because locked_ is no longer true.
        vm.prank(address(0x1234));
        vm.deal(address(0x1234), 1 wei);
        bool ok;
        try c.addToBalance{value: 1 wei}() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

