contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint112 amount, uint8 seed) public {
        vm.assume(amount > 0);
        address attacker = address(new ReentrantAttacker(c, seed));
        vm.deal(attacker, amount);

        uint256 balanceBefore = address(c).balance;
        vm.prank(attacker);
        c.addToBalance{value: amount}();
        uint256 balanceAfter = address(c).balance;

        assertTrue(balanceAfter - balanceBefore == amount);
    }
