import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 reentrantAmount) public {
        // Keep amounts positive and within bounds
        vm.assume(depositAmount > 0 && depositAmount < type(uint128).max);
        vm.assume(reentrantAmount > 0 && reentrantAmount < type(uint128).max);

        // Deploy a re-entrant attacker whose receive() calls back into addToBalance
        ReentrantAttacker attacker = new ReentrantAttacker(address(c), reentrantAmount);
        vm.deal(address(attacker), depositAmount + reentrantAmount);

        // Attacker first deposits via addToBalance
        attacker.deposit{value: depositAmount}();
        uint256 balanceBeforeWithdraw = c.getBalance(address(attacker));

        // Attacker withdraws, triggering re-entrant addToBalance during external call
        attacker.withdraw();

        // After withdrawal, userBalance must be 0 in the reference (nonReentrant blocks re-entrancy)
        // but can be non-zero in the mutant if re-entrancy succeeds.
        uint256 balanceAfter = c.getBalance(address(attacker));
        assertTrue(balanceAfter == 0);
    }
}

contract ReentrantAttacker {
    C target;
    uint256 reentrantAmount;
    bool reenter;

    constructor(address _target, uint256 _reentrantAmount) {
        target = C(payable(_target));
        reentrantAmount = _reentrantAmount;
    }

    function deposit() external payable {
        target.addToBalance{value: msg.value}();
    }

    function withdraw() external {
        reenter = true;
        target.withdrawBalance();
    }

    receive() external payable {
        if (reenter) {
            reenter = false;
            target.addToBalance{value: reentrantAmount}();
        }
    }
}

