pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 extraAmount) public {
        // 1. Keep amounts in admissible range: total cannot overflow
        uint256 maxUint = type(uint256).max;
        vm.assume(depositAmount <= maxUint - extraAmount);
        vm.assume(extraAmount <= maxUint - depositAmount);

        // 2. Deploy an adversarial re-entrant attacker helper
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));
        vm.deal(address(attacker), depositAmount + extraAmount);

        // Attacker deposits
        vm.prank(address(attacker));
        c.addToBalance{value: depositAmount}();

        // The attacker triggers withdrawBalance which calls back into addToBalance
        vm.prank(address(attacker));
        bool ok = true;
        try attacker.attack{value: extraAmount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // 3. Assert: Reference always succeeds the top-level addToBalance (attack always succeeds).
        // Buggy version re-enters and the modifier is missing, causing revert during reentrant addToBalance.
        assertTrue(ok);
    }
}

contract ReentrantAttacker {
    C public target;
    bool private attacking;

    constructor(address _target) {
        target = C(_target);
        attacking = false;
    }

    function attack() external payable {
        attacking = true;
        target.withdrawBalance();
        attacking = false;
    }

    receive() external payable {
        if (attacking && msg.sender == address(target)) {
            // re-enter addToBalance with zero value to test modifier presence
            target.addToBalance();
        }
    }
}

