pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposit1, uint256 deposit2, uint256 deposit3) public {
        // Bound deposits to reasonable values to avoid overflow, but keep wide
        deposit1 = bound(deposit1, 0, 1e60);
        deposit2 = bound(deposit2, 0, 1e60);
        deposit3 = bound(deposit3, 0, 1e60);

        // Deploy a re-entrant attacker that calls addToBalance during withdrawBalance
        ReentrantExploiter exploiter = new ReentrantExploiter(c);
        vm.deal(address(exploiter), deposit1 + deposit2 + deposit3);

        // User1 deposits
        vm.prank(address(exploiter));
        c.addToBalance{value: deposit1}();

        // User2 deposits
        address user2 = address(0x123);
        vm.deal(user2, deposit2);
        vm.prank(user2);
        c.addToBalance{value: deposit2}();

        // Exploiter deposits again (deposit3) and immediately withdraws, triggering re-entrancy
        exploiter.exploit{value: deposit3}();

        // After all calls, contract's ETH balance must equal sum of all user balances
        uint256 totalUserBalance = c.getBalance(address(exploiter)) + c.getBalance(user2);
        assertTrue(address(c).balance == totalUserBalance);
    }
}

contract ReentrantExploiter {
    C target;
    bool attacking;
    uint256 exploitAmount;

    constructor(C _target) {
        target = _target;
    }

    function exploit() external payable {
        exploitAmount = msg.value;
        attacking = true;
        target.addToBalance{value: msg.value}();
        target.withdrawBalance();
        attacking = false;
    }

    receive() external payable {
        if (attacking) {
            attacking = false;
            target.addToBalance{value: 0}();
            attacking = true;
        }
    }
}

