pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound amounts to plausible values (1 wei to 100 ETH to avoid overflow/zero)
        depositAmount = bound(depositAmount, 1, 100 ether);
        withdrawAmount = bound(withdrawAmount, 1, 100 ether);

        // Deploy a reentrant attacker that calls addToBalance during withdrawBalance
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // Fund the attacker contract
        vm.deal(address(attacker), depositAmount + withdrawAmount);

        // Attacker makes initial deposit
        attacker.deposit{value: depositAmount}();
        uint256 balanceBefore = attacker.getBalance();

        // Attacker triggers withdrawal which reenters addToBalance
        attacker.attack{value: withdrawAmount}();

        // After the attack, the attacker's balance should equal depositAmount + withdrawAmount
        // Reference: nonReentrant prevents reentrancy, so withdrawAmount is not credited
        // Bug: reentrant addToBalance credits withdrawAmount, resulting in double the expected increase
        uint256 balanceAfter = attacker.getBalance();
        assertTrue(balanceAfter == balanceBefore + withdrawAmount);
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public attackValue;

    constructor(C _target) {
        target = _target;
    }

    function deposit() external payable {
        target.addToBalance{value: msg.value}();
    }

    function attack() external payable {
        attackValue = msg.value;
        target.addToBalance{value: msg.value}();
        target.withdrawBalance();
    }

    function getBalance() public view returns (uint256) {
        return target.getBalance(address(this));
    }

    receive() external payable {
        // Re-enter addToBalance during withdrawBalance
        if (attackValue > 0) {
            uint256 val = attackValue;
            attackValue = 0; // prevent infinite loop
            target.addToBalance{value: val}();
        }
    }
}

