pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(amount > 0);

        // Setup: fund the actor and add balance to the contract
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        // Record pre-withdraw balances
        uint256 preUserBalance = c.getBalance(actor);
        uint256 preContractBalance = address(c).balance;

        // Perform withdraw
        vm.prank(actor);
        bool ok;
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert: if withdraw succeeded, contract balance must be 0 AND user balance must be 0
        if (ok) {
            assertTrue(address(c).balance == 0 && c.getBalance(actor) == 0);
        } else {
            // If withdraw reverted, user balance remains unchanged
            assertTrue(c.getBalance(actor) == preUserBalance);
        }
    }
}

