pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 amount, uint64 attackerSeed) public {
        vm.assume(amount > 0);
        address attacker = address(uint160(attackerSeed));
        vm.assume(attacker != address(0) && attacker != address(c));

        // Deploy a re-entrant attacker helper that calls withdrawBalance again during the ether transfer
        ReentrantAttacker helper = new ReentrantAttacker();
        address helperAddr = address(helper);

        // Fund the attacker account, then add its balance to the contract
        vm.deal(helperAddr, amount);
        vm.prank(helperAddr);
        c.addToBalance{value: amount}();

        // Set up the helper's target
        helper.setTarget(address(c));

        // Perform the withdrawal through the helper
        vm.prank(helperAddr);
        helper.attack();

        // After withdrawal completes, the attacker's balance in C must be 0
        uint256 balanceAfter = c.getBalance(helperAddr);
        assertTrue(balanceAfter == 0);
    }
}

contract ReentrantAttacker {
    C public target;
    bool private attacking;

    function setTarget(address _target) external {
        target = C(_target);
    }

    function attack() external {
        attacking = true;
        target.withdrawBalance();
        attacking = false;
    }

    receive() external payable {
        if (attacking) {
            // Re-enter withdrawBalance before the balance is set to 0
            target.withdrawBalance();
        }
    }
}

