pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 amount, uint64 reenterAmount) public {
        // bound amounts to avoid overflow in helper or contract
        bound(amount, 1, type(uint64).max);
        bound(reenterAmount, 1, type(uint64).max);

        // deploy a re-entrant attacker helper
        ReentrantAttacker attacker = new ReentrantAttacker(c, reenterAmount);
        address attackerAddr = address(attacker);

        // fund the contract with attacker's initial deposit
        vm.deal(attackerAddr, amount);
        vm.prank(attackerAddr);
        c.addToBalance{value: amount}();

        // attacker initiates withdrawal
        uint256 balanceBeforeWithdraw = c.getBalance(attackerAddr);
        vm.prank(attackerAddr);
        try attacker.attack() {
            // withdraw completed without reverting
        } catch {
            // if withdraw reverts, we skip assertion for this input (property only applies for successful withdrawals)
            return;
        }

        // After a successful withdrawal, the contract's recorded balance for the caller must be zero.
        // The buggy version removes reentrancy protection, allowing the attacker to re-enter via receive()
        // and call addToBalance(), resulting in non-zero final balance.
        uint256 balanceAfterWithdraw = c.getBalance(attackerAddr);
        assertTrue(balanceAfterWithdraw == 0);
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public reenterAmount;
    bool private attacking;

    constructor(C _target, uint256 _reenterAmount) {
        target = _target;
        reenterAmount = _reenterAmount;
    }

    function attack() external payable {
        attacking = true;
        target.withdrawBalance();
        attacking = false;
    }

    receive() external payable {
        if (attacking && address(target).balance >= reenterAmount) {
            target.addToBalance{value: reenterAmount}();
        }
    }
}

