pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 amount) public {
        // 1. Keep amount in admissible positive range
        vm.assume(amount > 0);
        // 2. Deploy a reentrant attacker that calls back into c during withdrawBalance
        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), amount);
        // 3. Attacker deposits and then withdraws, triggering reentrancy
        attacker.attack{value: amount}();
        // 4. The reference C (with nonReentrant_) will have zero balance after withdraw;
        //    the buggy M (without modifier) allows reentrant deposit, leaving non-zero balance.
        assertTrue(address(c).balance == 0);
    }
}

contract Attacker {
    C public target;
    bool private attacking;
    constructor(C _target) { target = _target; }
    function attack() external payable {
        target.addToBalance{value: msg.value}();
        target.withdrawBalance();
    }
    receive() external payable {
        if (!attacking && address(target).balance > 0) {
            attacking = true;
            target.addToBalance{value: 1 ether}();
            attacking = false;
        }
    }
}

