pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract ReentrantAttacker {
    C target;
    uint256 counter;
    constructor(C _target) payable { target = _target; }
    receive() external payable {
        if (counter < 1) {
            counter++;
            target.withdrawBalance();
        }
    }
    function attack(uint256 depositAmount) external payable {
        target.addToBalance{value: depositAmount}();
        target.withdrawBalance();
    }
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, address actor) public {
        vm.assume(depositAmount > 0 && depositAmount < 1 ether);
        vm.assume(actor != address(0) && actor != address(c));
        ReentrantAttacker attacker = new ReentrantAttacker{value: depositAmount}(c);
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        try attacker.attack{value: depositAmount}(depositAmount) {} catch {}
        uint256 bal = c.getBalance(address(attacker));
        assertTrue(bal == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address caller) public {
        // constrain amount to something reasonable; ensure caller is not address(c)
        amount = bound(amount, 1, 1000 ether);
        vm.assume(caller != address(0) && caller != address(c));

        // fund the caller and add balance to c
        vm.deal(caller, amount);
        vm.prank(caller);
        c.addToBalance{value: amount}();

        // record balance before withdrawal
        uint256 balBefore = c.getBalance(caller);
        require(balBefore == amount, "setup failed");

        // withdraw
        vm.prank(caller);
        (bool ok,) = address(c).call{value: 0}(abi.encodeWithSignature("withdrawBalance()"));
        require(ok, "withdraw did not succeed");

        // property: the caller's userBalance must be zero after a successful withdrawal
        uint256 balAfter = c.getBalance(caller);
        assertTrue(balAfter == 0, "balance not zero after withdraw");
    }
}
